<script setup lang="ts">
import {onBeforeUnmount,ref,watch} from 'vue';
import {LocalApiError,operationMessage,type LocalLauncherClient} from './local-api';
import type {ModDependency,ModFileRef,ModFile,ModFilesPage,ModProject,ModSource,TaskSnapshot} from './local-types';
const props=defineProps<{client:LocalLauncherClient;project:ModProject;gameVersion:string;loader:string;installAvailable?:boolean}>();
const emit=defineEmits<{submitted:[task:TaskSnapshot];install:[ref:ModFileRef];'open-project':[ref:{source:ModSource;projectId:string}];'rate-limit':[seconds:number]}>();
const page=ref<ModFilesPage|null>(null),loading=ref(false),busy=ref(''),error=ref(''),notice=ref(''),expired=ref(false),stale=ref(new Set<string>()),offset=ref(0),cooling=ref(false);
let sequence=0,controller=new AbortController(),timer:ReturnType<typeof setTimeout>|undefined;const lifetime=new AbortController();
const labels:Record<ModDependency['kind'],string>={REQUIRED:'必需',OPTIONAL:'可选',INCOMPATIBLE:'不兼容',EMBEDDED:'内嵌',TOOL:'工具',INCLUDE:'包含',UNKNOWN:'未知关系'};
const key=(file:ModFile)=>file.ref.versionId+':'+file.ref.fileKey;
function available(file:ModFile){return file.downloadable&&!!props.gameVersion&&!!props.loader&&file.gameVersions.includes(props.gameVersion)&&file.loaders.includes(props.loader)&&!stale.value.has(key(file))&&!expired.value&&!cooling.value;}
function failure(e:unknown){error.value=operationMessage(e);if(e instanceof LocalApiError){if(e.status===401||e.status===403)expired.value=true;if(e.status===429){cooling.value=true;const seconds=e.retryAfterSeconds??60;emit('rate-limit',seconds);clearTimeout(timer);timer=setTimeout(()=>cooling.value=false,seconds*1000);}}}
async function load(reset=true,change=0){if(expired.value||cooling.value)return;controller.abort();controller=new AbortController();const current=++sequence;const next=reset?0:Math.max(0,offset.value+change*20);loading.value=true;error.value='';notice.value='';stale.value=new Set();
 try{const value=await props.client.modFiles(props.project.source,props.project.projectId,{gameVersion:props.gameVersion,loader:props.loader,offset:next,limit:20},controller.signal);if(current===sequence){page.value=value;offset.value=next;}}
 catch(e){if(current===sequence&&!(e instanceof DOMException&&e.name==='AbortError'))failure(e);}finally{if(current===sequence)loading.value=false;}}
async function download(file:ModFile){if(busy.value||!available(file))return;busy.value=key(file);error.value='';notice.value='';try{const result=await props.client.downloadMod(file.ref,props.gameVersion,props.loader,lifetime.signal);notice.value='已加入下载任务，校验通过后保存到模组库。';emit('submitted',result.task);}catch(e){failure(e);if(e instanceof LocalApiError&&e.status===409){stale.value=new Set([...stale.value,key(file)]);error.value+='；请刷新文件列表后重新选择。';}}finally{busy.value='';}}
watch([()=>props.project.source,()=>props.project.projectId,()=>props.gameVersion,()=>props.loader],()=>{page.value=null;void load();},{immediate:true});
onBeforeUnmount(()=>{++sequence;controller.abort();lifetime.abort();clearTimeout(timer);});
</script>
<template>
 <section class="launcher-mod-files launcher-glass" data-mod-files><div class="launcher-modal-title"><div><span class="launcher-overline">OFFICIAL FILES</span><h2>{{project.title||project.projectId}}</h2></div><button class="launcher-secondary" data-refresh-mod-files :disabled="loading||!!busy||expired||cooling" @click="load()">刷新文件 ↻</button></div><p class="launcher-caption">{{project.summary}}</p><p v-if="!gameVersion||!loader" class="launcher-inline-notice">先明确选择游戏版本与加载器，再下载兼容文件。依赖只作说明，不会自动安装。</p><p v-if="error" class="launcher-inline-notice" role="alert">{{error}}</p><p v-if="notice" class="launcher-inline-notice" role="status">{{notice}}</p><p v-if="loading" class="launcher-caption" role="status">正在读取官方文件列表…</p><p v-if="page?.platformLimited" class="launcher-inline-notice">来源共报告 {{page.total}} 项，平台仅允许访问前 {{page.accessibleTotal}} 项。</p><p v-if="page&&!loading&&!page.items.length" class="launcher-caption">没有符合当前版本和加载器的文件，不会自动放宽条件。</p>
 <article v-for="file in page?.items" :key="key(file)" :data-mod-file-key="file.ref.fileKey" class="launcher-mod-file-row"><div class="launcher-mod-file-title"><div><h3>{{file.displayName||file.fileName}}</h3><small>{{file.fileName}} · {{file.releaseChannel||'发布渠道未提供'}} · {{file.size===null?'大小未提供':(file.size/1048576).toFixed(2)+' MiB'}}</small></div><button v-if="installAvailable" class="launcher-secondary" data-install-mod :disabled="!!busy||!available(file)" @click="emit('install',file.ref)">装入实例…</button><button class="launcher-primary" data-download-mod :disabled="!!busy||!available(file)" @click="download(file)">{{busy===key(file)?'正在提交…':'下载到模组库'}}</button></div><div class="launcher-tool-tags"><span v-for="version in file.gameVersions" :key="version">{{version}}</span><span v-for="tag in file.loaders" :key="tag">{{tag}}</span></div><p v-if="file.blockedReason" class="launcher-caption">不可下载 · {{file.blockedReason}}</p><p v-if="file.sourceDigest" class="launcher-mod-digest">{{file.sourceDigest.algorithm}} · {{file.sourceDigest.hex}}</p><div v-if="file.dependencies.length" class="launcher-mod-dependencies"><span class="launcher-caption">依赖说明</span><template v-for="(dependency,index) in file.dependencies" :key="index"><button v-if="dependency.projectId" class="launcher-dependency" data-open-dependency @click="emit('open-project',{source:project.source,projectId:dependency.projectId})">{{labels[dependency.kind]}} · {{dependency.projectId}} ↗</button><span v-else class="launcher-dependency">{{labels[dependency.kind]}} · {{dependency.versionId||dependency.fileName||'未提供引用'}}</span></template></div></article>
 <div v-if="page&&page.accessibleTotal>20" class="launcher-task-pagination"><button class="launcher-secondary" :disabled="!offset||loading||expired||cooling" @click="load(false,-1)">上一页</button><span>{{offset+1}}–{{Math.min(offset+20,page.accessibleTotal)}} / {{page.accessibleTotal}}</span><button class="launcher-secondary" :disabled="offset+20>=page.accessibleTotal||loading||expired||cooling" @click="load(false,1)">下一页</button></div></section>
</template>
